useEffect(() => {
  setStatus('loading');

  fetchSearch(query)
    .then((items) => {
      setResults(items);
    })
    .catch((error) => {
      setError(error);
    })
    .finally(() => {
      setStatus('idle');
    });
}, [query]);

@Component({
  selector: 'user-card',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `{{ user.name }}`
})
export class UserCardComponent {
  @Input() user!: User;
}

// Parent component
rename(nextName: string) {
  this.user.name = nextName;
}
